code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    templates = []
    # Find an isolated odd-length straight motif. Its middle cell is the
    # alignment point for each scattered marker.
    for dr, dc in ((0, 1), (1, 0)):
        for r in range(h):
            for c in range(w):
                if grid[r][c] == bg:
                    continue
                # Only start at the beginning of a maximal run.
                pr, pc = r-dr, c-dc
                if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] != bg:
                    continue
                cells = []
                rr, cc = r, c
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] != bg:
                    cells.append((rr, cc))
                    rr += dr
                    cc += dc
                n = len(cells)
                if n < 3 or n % 2 == 0:
                    continue
                S = set(cells)
                isolated = True
                for rr, cc in cells:
                    for ar in range(max(0, rr-1), min(h, rr+2)):
                        for ac in range(max(0, cc-1), min(w, cc+2)):
                            if (ar, ac) not in S and grid[ar][ac] != bg:
                                isolated = False
                if isolated:
                    templates.append((dr, dc, [grid[rr][cc] for rr, cc in cells]))
    if not templates:
        return [row[:] for row in grid]
    dr, dc, pattern = templates[0]
    pattern_colors = set(pattern)
    others = Counter(v for row in grid for v in row if v != bg and v not in pattern_colors)
    if not others:
        return [row[:] for row in grid]
    marker = others.most_common(1)[0][0]
    out = [row[:] for row in grid]
    mid = len(pattern) // 2
    for r in range(h):
        for c in range(w):
            if grid[r][c] == marker:
                for i, color in enumerate(pattern):
                    rr = r + (i-mid)*dr
                    cc = c + (i-mid)*dc
                    if 0 <= rr < h and 0 <= cc < w:
                        out[rr][cc] = color
    return out
